package com.anpfuel.data.map

import java.io.File
import java.util.Base64
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

/**
 * The committed `contracts/testdata/map/dist-kotlin-v1` envelope carries a
 * real Go `crypto/ed25519` signature (generated by
 * `backend/internal/modules/mapdist`, private key ephemeral and discarded).
 * These tests prove the app verifies exactly those Go bytes through both the
 * platform path and the owned Monocypher bridge (the bridge itself is proven
 * on-device in `MonocypherEd25519InstrumentedTest`).
 */
class MapManifestGoFixtureTest {
    private fun fixtureDir(): File {
        var dir = File(System.getProperty("user.dir"))
        repeat(8) {
            val candidate = File(dir, "contracts/testdata/map/dist-kotlin-v1")
            if (File(candidate, "distribution.json").isFile) return candidate
            dir = dir.parentFile ?: return@repeat
        }
        throw IllegalStateException("committed Go fixture not found")
    }

    private fun envelope(): String = File(fixtureDir(), "distribution.json").readText()

    private fun pubKey(): ByteArray {
        val raw = File(fixtureDir(), "test-key.pub").readText().trim()
        val padded = raw + "=".repeat((4 - raw.length % 4) % 4)
        return Base64.getUrlDecoder().decode(padded)
    }

    @Test fun `go-signed envelope verifies with pinned raw key`() {
        val verified = MapManifestVerifier.verify(envelope(), mapOf("test-key" to pubKey()))
        assertEquals("test-20261025.1", verified.manifest.generation)
        assertEquals("2601", verified.manifest.formatVersion)
        assertEquals("test-key", verified.keyId)
        assertEquals(2, verified.manifest.packages.size)
    }

    @Test fun `go-signed envelope rejects cloned key, tamper and truncation`() {
        val raw = envelope()
        // Unknown key id fails closed before any crypto.
        assertThrows(MapSignatureException::class.java) {
            MapManifestVerifier.verify(raw, mapOf("other" to pubKey()))
        }
        // Wrong key material fails as an invalid signature.
        assertThrows(MapSignatureException::class.java) {
            MapManifestVerifier.verify(raw, mapOf("test-key" to ByteArray(32) { (it + 1).toByte() }))
        }
        // Truncated signature fails closed (decode or size gate).
        val truncated = org.json.JSONObject(raw).apply {
            put("signature", getString("signature").dropLast(8))
        }.toString()
        assertThrows(Exception::class.java) {
            MapManifestVerifier.verify(truncated, mapOf("test-key" to pubKey()))
        }
        // Altered manifest bytes fail on the hash gate.
        val manifest = org.json.JSONObject(raw).getString("manifest")
        val tamperedManifest = manifest.dropLast(4) + "AAAA"
        val tampered = org.json.JSONObject(raw).apply { put("manifest", tamperedManifest) }.toString()
        assertThrows(Exception::class.java) {
            MapManifestVerifier.verify(tampered, mapOf("test-key" to pubKey()))
        }
    }

    @Test fun `monocypher bridge verifies the same go bytes`() {
        // JNI .so ships for Android ABIs only; on the JVM the bridge reports
        // unavailable and must fail closed instead of throwing.
        val raw = envelope()
        val root = org.json.JSONObject(raw)
        fun b64(s: String): ByteArray {
            val padded = s + "=".repeat((4 - s.length % 4) % 4)
            return Base64.getUrlDecoder().decode(padded)
        }
        val msg = b64(root.getString("manifest"))
        val sig = b64(root.getString("signature"))
        assertEquals(64, sig.size)
        if (MonocypherEd25519.isAvailable()) {
            assertTrue(MonocypherEd25519.verifyRaw(pubKey(), msg, sig))
            val bad = sig.copyOf().also { it[0] = (it[0].toInt() xor 1).toByte() }
            assertTrue(!MonocypherEd25519.verifyRaw(pubKey(), msg, bad))
        } else {
            assertTrue(!MonocypherEd25519.verifyRaw(pubKey(), msg, sig))
        }
    }

    @Test fun `key parser accepts pinned entries and refuses malformed config`() {
        val keys = MapDistributionKeys.parse("test-key:${File(fixtureDir(), "test-key.pub").readText().trim()}")
        assertEquals(32, keys["test-key"]!!.size)
        assertTrue(MapDistributionKeys.parse("").isEmpty())
        assertTrue(MapDistributionKeys.parse("   ").isEmpty())
        assertThrows(com.anpfuel.domain.map.MapContractException::class.java) {
            MapDistributionKeys.parse("no-separator")
        }
        assertThrows(com.anpfuel.domain.map.MapContractException::class.java) {
            MapDistributionKeys.parse("k:!!!not-base64!!!")
        }
        assertThrows(com.anpfuel.domain.map.MapContractException::class.java) {
            MapDistributionKeys.parse("k:AAAA")
        }
        assertThrows(com.anpfuel.domain.map.MapContractException::class.java) {
            val dup = "a:${keys["test-key"]!!.let { java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(it) }}"
            MapDistributionKeys.parse("$dup,$dup")
        }
    }
}
